-- ════════════════════════════════════════════════════════════════════════
-- MIGRACIÓN 054 — curso nuevo "Evaluación del Paciente y Signos Vitales"
-- ════════════════════════════════════════════════════════════════════════
-- Contenido original — el PDF de referencia en public/cursos/ solo se usó
-- para decidir qué temas cubrir y en qué orden (evaluación primaria,
-- AVDI, ABC, prioridad, signos vitales, evaluación secundaria), siguiendo
-- el enfoque TUM/paramédico que pidió el usuario. Diagramas SVG propios.

insert into public.courses (id, title, description, ai_instructions, icon, color, category, subcategory, locked, modules)
values (
  'course-valoracion-paciente',
  'Evaluación del Paciente y Signos Vitales',
  'El método que usan los profesionales de emergencias para evaluar a un paciente en minutos: impresión general, AVDI, ABC, prioridad del paciente y cómo medir e interpretar los signos vitales.',
  'Eres el Zorro Mago, tutor de evaluación de pacientes en Oliver Academy. Enseña el método (impresión general → AVDI → ABC → prioridad → signos vitales → evaluación secundaria) como una secuencia lógica que existe para no pasar por alto nada bajo presión, no como una lista para memorizar sin entender el porqué de cada paso.',
  '🩹',
  '#38bdf8',
  'Medicina',
  'Evaluación del Paciente',
  false,
  '[{"id":1,"order":1,"type":"text","title":"Bienvenida: por qué existe un método para evaluar a un paciente","description":"No es \"ver qué tiene\" al ojo — es un procedimiento repetible que no deja pasar nada grave.","content":"<h2>El problema de improvisar</h2><p>Ante una emergencia real, el estrés hace que sea fácil pasar por alto algo crítico. Por eso el personal de emergencias médicas (TUM/paramédicos) sigue un <strong>método estructurado</strong> para evaluar a cualquier paciente, en el mismo orden, cada vez — no porque falte criterio, sino porque bajo presión un método confiable vence a la memoria.</p>\n  <h2>Dos grandes evaluaciones</h2><p>Este curso cubre las dos fases clásicas de la valoración de un paciente: la <strong>evaluación primaria</strong> (encontrar y tratar amenazas inmediatas a la vida, en minutos) y los <strong>signos vitales</strong> (medir objetivamente qué tan bien está funcionando el cuerpo en ese momento).</p>\n  <div class=\"tip\">💡 Esta misma lógica — un checklist fijo en vez de confiar en la memoria bajo presión — es la razón por la que los pilotos usan listas de verificación antes de despegar, aunque lleven 20 años volando.</div>\n  <div class=\"warn\">⚠️ Este curso es divulgación sobre el método de evaluación que usan los profesionales de emergencias — no te certifica como TUM ni reemplaza un entrenamiento formal y práctico.</div>","exercises":[{"id":"vp-01-1","type":"challenge","prompt":"¿Se te ocurre otra profesión (además de pilotos) donde seguir un método fijo, paso a paso, sea más confiable que improvisar bajo presión? Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿Por qué se usa un método fijo para evaluar pacientes, en vez de improvisar?","options":["Porque lo exige la ley únicamente","Porque bajo estrés es fácil pasar por alto algo grave, y un método fijo no depende de la memoria","Porque es más rápido siempre","No hay una razón real, es solo tradición"],"correctIndex":1},"comments":[]},{"id":2,"order":2,"type":"text","title":"Impresión general y estado mental: los primeros 10 segundos","description":"Antes de tocar al paciente, ya estás recolectando información crítica.","content":"<h2>La impresión general</h2><p>Al acercarte a un paciente, en los primeros segundos ya observas su ambiente, su postura, su color de piel y cómo respira. Esa <strong>impresión general</strong> es subjetiva, pero da una idea rápida de qué tan urgente es la situación, antes de medir nada formalmente.</p>\n  <h2>AVDI: clasificar el estado mental en un instante</h2>\n  <svg viewBox=\"0 0 460 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:520px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<rect x=\"10\" y=\"15\" width=\"100\" height=\"80\" rx=\"10\" fill=\"#4ade80\" opacity=\"0.85\"/><text x=\"60\" y=\"55\" font-size=\"26\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">A</text><text x=\"60\" y=\"82\" font-size=\"10\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">Alerta</text>\n<rect x=\"125\" y=\"15\" width=\"100\" height=\"80\" rx=\"10\" fill=\"#facc15\" opacity=\"0.85\"/><text x=\"175\" y=\"55\" font-size=\"26\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">V</text><text x=\"175\" y=\"82\" font-size=\"10\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">Responde a la voz</text>\n<rect x=\"240\" y=\"15\" width=\"100\" height=\"80\" rx=\"10\" fill=\"#fb923c\" opacity=\"0.85\"/><text x=\"290\" y=\"55\" font-size=\"26\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">D</text><text x=\"290\" y=\"82\" font-size=\"10\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">Responde al dolor</text>\n<rect x=\"355\" y=\"15\" width=\"100\" height=\"80\" rx=\"10\" fill=\"#f87171\" opacity=\"0.85\"/><text x=\"405\" y=\"55\" font-size=\"26\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">I</text><text x=\"405\" y=\"82\" font-size=\"10\" fill=\"#0f172a\" text-anchor=\"middle\" font-family=\"sans-serif\">No responde</text>\n</svg>\n  <p>El estado mental se clasifica con la nemotecnia <strong>AVDI</strong>: ¿está <strong>A</strong>lerta? ¿Responde a estímulo <strong>V</strong>erbal (una voz, una pregunta)? ¿Responde solo a estímulo <strong>D</strong>oloroso (un pellizco)? ¿O no responde en absoluto (<strong>I</strong>nconsciente)?</p>\n  <div class=\"example\">🧪 Un paciente \"alerta\" no solo tiene los ojos abiertos — idealmente está orientado en persona, lugar y tiempo (sabe quién es, dónde está y qué día es aproximadamente). Perder la orientación en tiempo suele ser lo primero en irse cuando algo anda mal.</div>\n  <div class=\"tip\">💡 AVDI es rápido a propósito — no es un examen neurológico completo, es una primera clasificación en segundos para decidir qué tan urgente es todo lo que sigue.</div>","exercises":[{"id":"vp-02-1","type":"challenge","prompt":"Explica con tus palabras qué significa cada letra de AVDI y da un ejemplo de cómo se vería un paciente en cada nivel. Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"En la nemotecnia AVDI, ¿qué significa la \"D\"?","options":["Diabético","Responde a estímulo Doloroso","Debilidad","Desorientado únicamente"],"correctIndex":1},"comments":[]},{"id":3,"order":3,"type":"text","title":"ABC: vía aérea, respiración y circulación","description":"El núcleo de la evaluación primaria — tres preguntas que pueden decidir si alguien sobrevive los próximos minutos.","content":"<h2>Tres preguntas, en orden</h2>\n  <svg viewBox=\"0 0 420 140\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:480px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<rect x=\"10\" y=\"30\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#38bdf8\"/>\n<text x=\"70\" y=\"60\" font-size=\"20\" font-weight=\"bold\" fill=\"#0c2a3d\" text-anchor=\"middle\" font-family=\"sans-serif\">A</text>\n<text x=\"70\" y=\"82\" font-size=\"11\" fill=\"#0c2a3d\" text-anchor=\"middle\" font-family=\"sans-serif\">Vía aérea</text>\n<path d=\"M132 65 L163 65\" stroke=\"#64748b\" stroke-width=\"3\"/>\n<rect x=\"150\" y=\"30\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#facc15\"/>\n<text x=\"210\" y=\"60\" font-size=\"20\" font-weight=\"bold\" fill=\"#422006\" text-anchor=\"middle\" font-family=\"sans-serif\">B</text>\n<text x=\"210\" y=\"82\" font-size=\"11\" fill=\"#422006\" text-anchor=\"middle\" font-family=\"sans-serif\">Respiración</text>\n<path d=\"M272 65 L303 65\" stroke=\"#64748b\" stroke-width=\"3\"/>\n<rect x=\"290\" y=\"30\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#f87171\"/>\n<text x=\"350\" y=\"60\" font-size=\"20\" font-weight=\"bold\" fill=\"#450a0a\" text-anchor=\"middle\" font-family=\"sans-serif\">C</text>\n<text x=\"350\" y=\"82\" font-size=\"11\" fill=\"#450a0a\" text-anchor=\"middle\" font-family=\"sans-serif\">Circulación</text>\n<text x=\"210\" y=\"120\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"middle\" font-family=\"sans-serif\">se revisa en este orden — salvo paro cardiaco, donde se invierte a C-A-B</text>\n</svg>\n  <p><strong>A — Vía aérea:</strong> ¿está despejada? Algo tan simple como la lengua puede obstruirla en una persona inconsciente. <strong>B — Respiración:</strong> ¿respira, y a una frecuencia y esfuerzo razonables? <strong>C — Circulación:</strong> ¿tiene pulso? ¿hay hemorragia visible que controlar ya?</p>\n  <h2>Cuando el orden se invierte: C-A-B</h2><p>Para un paciente que no muestra signos de vida (no responde, no respira con normalidad), las guías actuales de reanimación recomiendan empezar directamente por <strong>circulación</strong> — revisar pulso e iniciar compresiones torácicas si no lo hay — antes de detenerse en la vía aérea. Cada segundo sin circulación cuenta más que cualquier otra cosa en ese escenario específico.</p>\n  <div class=\"tip\">💡 El ABC no es una lista rígida de \"un paso, luego el siguiente\" — es una guía de prioridades. Si encuentras un problema grave en \"A\", casi siempre lo corriges de inmediato antes de seguir a \"B\".</div>","exercises":[{"id":"vp-03-1","type":"challenge","prompt":"Explica con tus palabras en qué situación se usaría la secuencia C-A-B en vez de A-B-C, y por qué. Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿Cuándo se usa la secuencia C-A-B en vez de A-B-C?","options":["Siempre, es la única secuencia correcta","Cuando el paciente no muestra signos de vida (posible paro cardiaco)","Solo en niños","Nunca se invierte el orden"],"correctIndex":1},"comments":[]},{"id":4,"order":4,"type":"text","title":"Prioridad del paciente: ¿esperar o trasladar ya?","description":"Una de las decisiones más importantes de toda la evaluación: qué tan urgente es sacar a esta persona de ahí.","content":"<h2>Tres categorías</h2>\n  <svg viewBox=\"0 0 420 130\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:480px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"70\" cy=\"55\" r=\"35\" fill=\"#4ade80\"/>\n<text x=\"70\" y=\"60\" font-size=\"12\" fill=\"#052e16\" text-anchor=\"middle\" font-family=\"sans-serif\">Estable</text>\n<text x=\"70\" y=\"105\" font-size=\"10\" fill=\"#bbf7d0\" text-anchor=\"middle\" font-family=\"sans-serif\">puede esperar</text>\n<circle cx=\"210\" cy=\"55\" r=\"40\" fill=\"#facc15\"/>\n<text x=\"210\" y=\"52\" font-size=\"12\" fill=\"#422006\" text-anchor=\"middle\" font-family=\"sans-serif\">Potencialmente</text>\n<text x=\"210\" y=\"66\" font-size=\"12\" fill=\"#422006\" text-anchor=\"middle\" font-family=\"sans-serif\">inestable</text>\n<text x=\"210\" y=\"105\" font-size=\"10\" fill=\"#fde68a\" text-anchor=\"middle\" font-family=\"sans-serif\">vigilar de cerca</text>\n<circle cx=\"360\" cy=\"55\" r=\"45\" fill=\"#f87171\"/>\n<text x=\"360\" y=\"60\" font-size=\"13\" fill=\"#450a0a\" text-anchor=\"middle\" font-family=\"sans-serif\">Inestable</text>\n<text x=\"360\" y=\"112\" font-size=\"10\" fill=\"#fecaca\" text-anchor=\"middle\" font-family=\"sans-serif\">traslado inmediato</text>\n</svg>\n  <p>Con base en la impresión general, el AVDI y el ABC, se clasifica al paciente en una de tres categorías de <strong>prioridad</strong>: <strong>estable</strong> (puede esperar sin riesgo mientras se completa la evaluación), <strong>potencialmente inestable</strong> (parece estar bien, pero algo en el cuadro genera alerta — hay que vigilarlo de cerca) o <strong>inestable</strong> (traslado inmediato, la evaluación detallada continúa en el trayecto).</p>\n  <div class=\"example\">🧪 Una persona de 62 años que solo se queja de debilidad, se ve pálida y sudorosa, está alerta y sin problemas evidentes en el ABC — pero \"algo no cuadra\" para quien la evalúa — es exactamente el tipo de caso que se clasifica como potencialmente inestable: los números aún no son alarmantes, pero la intuición clínica entrenada sí lo es.</div>\n  <div class=\"tip\">💡 La prioridad puede cambiar en cualquier momento — un paciente \"estable\" puede volverse inestable si su condición empeora, por eso la evaluación es continua, no una sola decisión al inicio.</div>","exercises":[{"id":"vp-04-1","type":"challenge","prompt":"Piensa en un síntoma que por sí solo parecería leve, pero que combinado con el contexto (edad, palidez, sudoración) haría que alguien lo clasificara como \"potencialmente inestable\". Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿Qué significa que un paciente sea \"potencialmente inestable\"?","options":["Que ya está en paro cardiaco","Que parece razonablemente bien, pero algo en el cuadro amerita vigilancia cercana","Que definitivamente no necesita ayuda","Que es un niño"],"correctIndex":1},"comments":[]},{"id":5,"order":5,"type":"text","title":"Signos vitales I: pulso, respiración, piel y temperatura","description":"Números concretos que reemplazan a \"se ve mal\" — y permiten comparar cómo cambia un paciente con el tiempo.","content":"<h2>Por qué medir, no solo observar</h2><p>Los <strong>signos vitales</strong> convierten \"el paciente se ve mal\" en números objetivos y comparables — lo que permite notar si alguien está mejorando o empeorando entre una medición y la siguiente.</p>\n  <h2>Pulso: dónde y cómo tomarlo</h2>\n  <svg viewBox=\"0 0 200 380\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:220px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"100\" cy=\"40\" r=\"28\" fill=\"#334155\"/>\n<rect x=\"75\" y=\"65\" width=\"50\" height=\"70\" rx=\"14\" fill=\"#334155\"/>\n<rect x=\"60\" y=\"130\" width=\"30\" height=\"90\" rx=\"10\" fill=\"#334155\"/>\n<rect x=\"110\" y=\"130\" width=\"30\" height=\"90\" rx=\"10\" fill=\"#334155\"/>\n<rect x=\"70\" y=\"215\" width=\"25\" height=\"120\" rx=\"10\" fill=\"#334155\"/>\n<rect x=\"105\" y=\"215\" width=\"25\" height=\"120\" rx=\"10\" fill=\"#334155\"/>\n<circle cx=\"103\" cy=\"72\" r=\"6\" fill=\"#f87171\"/>\n<text x=\"150\" y=\"76\" fill=\"#fca5a5\" font-size=\"10\" font-family=\"sans-serif\">carotídeo</text>\n<circle cx=\"80\" cy=\"140\" r=\"6\" fill=\"#f87171\"/>\n<text x=\"20\" y=\"130\" fill=\"#fca5a5\" font-size=\"10\" font-family=\"sans-serif\">braquial</text>\n<circle cx=\"70\" cy=\"222\" r=\"6\" fill=\"#f87171\"/>\n<text x=\"10\" y=\"222\" fill=\"#fca5a5\" font-size=\"10\" font-family=\"sans-serif\">radial</text>\n<circle cx=\"82\" cy=\"330\" r=\"6\" fill=\"#f87171\"/>\n<text x=\"20\" y=\"355\" fill=\"#fca5a5\" font-size=\"10\" font-family=\"sans-serif\">pedio</text>\n</svg>\n  <p>El pulso se puede tomar en varios puntos donde una arteria pasa cerca de la superficie: <strong>carotídeo</strong> (cuello), <strong>braquial</strong> (interior del brazo, común en bebés), <strong>radial</strong> (muñeca) y <strong>pedio</strong> (empeine del pie). Se registra la frecuencia (latidos por minuto) y también el ritmo y la fuerza.</p>\n  <h2>Respiración</h2><p>Se cuenta la frecuencia respiratoria (respiraciones por minuto) y se observa si es fácil o con esfuerzo, profunda o superficial, y si el paciente usa músculos adicionales del cuello o el tórax para respirar — una señal de dificultad real.</p>\n  <h2>Piel y temperatura</h2><p>El color, la temperatura y la humedad de la piel (pálida y sudorosa, por ejemplo) son un indicador rápido de circulación y de la actividad del sistema nervioso simpático (la respuesta de estrés del cuerpo).</p>\n  <div class=\"tip\">💡 Un solo signo vital dice poco por sí mismo — su valor real está en tomarlos varias veces y comparar la tendencia: ¿el pulso sube con el tiempo? ¿la piel pasa de normal a pálida y sudorosa? Esa tendencia es la información más valiosa.</div>","exercises":[{"id":"vp-05-1","type":"challenge","prompt":"Tómate el pulso en la muñeca (radial) durante 30 segundos y multiplica por 2. Anota el número y compártelo con tu mascota junto con cómo describirías tu respiración en este momento (fácil, profunda, etc).","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿Por qué es más útil tomar los signos vitales varias veces en vez de una sola?","options":["No lo es, una sola medición siempre basta","Porque la tendencia (si mejora o empeora con el tiempo) es más informativa que un solo número","Porque el aparato se puede descomponer","Solo se toman varias veces en niños"],"correctIndex":1},"comments":[]},{"id":6,"order":6,"type":"text","title":"Signos vitales II: presión arterial y oxigenación","description":"Dos mediciones más técnicas, pero igual de reveladoras sobre cómo está funcionando el cuerpo por dentro.","content":"<h2>Presión arterial: dos números, un significado</h2>\n  <svg viewBox=\"0 0 300 160\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:340px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"90\" cy=\"80\" r=\"60\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"3\"/>\n<line x1=\"90\" y1=\"80\" x2=\"90\" y2=\"35\" stroke=\"#f87171\" stroke-width=\"3\"/>\n<circle cx=\"90\" cy=\"80\" r=\"4\" fill=\"#f87171\"/>\n<text x=\"90\" y=\"150\" fill=\"#94a3b8\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">manómetro</text>\n<rect x=\"180\" y=\"50\" width=\"100\" height=\"55\" rx=\"12\" fill=\"#475569\"/>\n<text x=\"230\" y=\"82\" fill=\"#e2e8f0\" font-size=\"14\" text-anchor=\"middle\" font-family=\"sans-serif\">120/80</text>\n<text x=\"230\" y=\"123\" fill=\"#94a3b8\" font-size=\"10\" text-anchor=\"middle\" font-family=\"sans-serif\">sistólica / diastólica</text>\n</svg>\n  <p>La presión arterial se reporta como dos números: la <strong>sistólica</strong> (presión cuando el corazón se contrae y bombea) sobre la <strong>diastólica</strong> (presión cuando el corazón se relaja entre latidos). Un valor típico en un adulto sano ronda 120/80 mmHg, aunque el rango normal varía por persona.</p>\n  <h2>Saturación de oxígeno</h2><p>Un oxímetro de pulso (el clip que se coloca en un dedo) mide qué porcentaje de la hemoglobina de la sangre está transportando oxígeno. Es una forma rápida y no invasiva de detectar problemas respiratorios antes de que sean obvios a simple vista.</p>\n  <div class=\"example\">🧪 Una presión arterial que baja progresivamente en mediciones repetidas, combinada con un pulso que sube, es un patrón clásico de alarma — el cuerpo está compensando una pérdida de volumen sanguíneo o de función circulatoria, y ese patrón se detecta antes gracias a mediciones repetidas, no a una sola.</div>\n  <div class=\"tip\">💡 Estos aparatos son herramientas, no reemplazos del criterio clínico — un oxímetro puede dar lecturas engañosas si el paciente tiene las manos muy frías o está en movimiento, por eso siempre se interpreta junto con el resto de la evaluación.</div>","exercises":[{"id":"vp-06-1","type":"challenge","prompt":"Explica con tus palabras qué mide el número \"sistólico\" y qué mide el \"diastólico\" en una lectura de presión arterial. Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿Qué mide un oxímetro de pulso?","options":["La presión arterial","El porcentaje de hemoglobina que transporta oxígeno","La temperatura corporal","El ritmo cardíaco eléctrico detallado"],"correctIndex":1},"comments":[]},{"id":7,"order":7,"type":"text","title":"Evaluación secundaria: de la cabeza a los pies","description":"Una vez controladas las amenazas inmediatas a la vida, toca buscar todo lo demás, de forma sistemática.","content":"<h2>Después de lo urgente, lo completo</h2><p>Una vez que la evaluación primaria descarta o controla amenazas inmediatas a la vida, la <strong>evaluación secundaria</strong> es un repaso ordenado, región por región, en busca de cualquier otra lesión o problema que no sea evidente de inmediato.</p>\n  <svg viewBox=\"0 0 160 340\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:180px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"80\" cy=\"35\" r=\"26\" fill=\"#a78bfa\"/>\n<text x=\"120\" y=\"40\" fill=\"#ddd6fe\" font-size=\"11\" font-family=\"sans-serif\">cabeza</text>\n<rect x=\"55\" y=\"65\" width=\"50\" height=\"30\" rx=\"8\" fill=\"#818cf8\"/>\n<text x=\"120\" y=\"85\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">cuello</text>\n<rect x=\"45\" y=\"100\" width=\"70\" height=\"70\" rx=\"10\" fill=\"#6366f1\"/>\n<text x=\"125\" y=\"140\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">tórax</text>\n<rect x=\"48\" y=\"175\" width=\"64\" height=\"55\" rx=\"10\" fill=\"#4f46e5\"/>\n<text x=\"125\" y=\"205\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">abdomen/pelvis</text>\n<rect x=\"40\" y=\"235\" width=\"30\" height=\"95\" rx=\"10\" fill=\"#4338ca\"/>\n<rect x=\"90\" y=\"235\" width=\"30\" height=\"95\" rx=\"10\" fill=\"#4338ca\"/>\n<text x=\"125\" y=\"290\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">extremidades</text>\n</svg>\n  <p>El orden clásico va de la <strong>cabeza</strong> al <strong>cuello</strong>, <strong>tórax</strong>, <strong>abdomen y pelvis</strong>, y finalmente las <strong>extremidades</strong> — buscando en cada región deformidades, heridas, sensibilidad al tacto, hinchazón o cualquier cosa fuera de lo normal.</p>\n  <div class=\"tip\">💡 Ir siempre en el mismo orden, sistema por región, es lo que evita que una lesión secundaria (un tobillo torcido, por ejemplo) pase completamente desapercibida mientras la atención está en algo más dramático.</div>\n  <div class=\"warn\">⚠️ En un paciente inestable, la evaluación secundaria puede posponerse o hacerse en el trayecto al hospital — la prioridad siempre es corregir primero lo que amenaza la vida de inmediato.</div>","exercises":[{"id":"vp-07-1","type":"challenge","prompt":"Resume con tus palabras, en una lista de 5 pasos, el orden completo que aprendiste en este curso: desde que te acercas a un paciente hasta terminar la evaluación secundaria. Compártelo con tu mascota.","solution":""}],"resources":[],"noChat":true,"quiz":{"question":"¿En qué momento se realiza normalmente la evaluación secundaria?","options":["Antes que la evaluación primaria, siempre","Después de controlar las amenazas inmediatas a la vida encontradas en la evaluación primaria","Nunca, solo existe la evaluación primaria","Solo en pacientes que ya están en el hospital"],"correctIndex":1},"comments":[]}]'::jsonb
)
on conflict (id) do nothing;
